// CCM builds draft guidance for the exact pinned collaborative monitoring inventory.
func CCM(rules, markdown fs.FS) (readiness.Package, error) {
	return communicationDraft(rules, markdown, "CCM", "collaborative-continuous-monitoring", 107, ccmRecipes, []communicationCapability{
		{"ccm-report-cycle", "Ongoing report production and delivery", "Certification reporting owner", "Map the service's certification-data changes, vulnerability decisions, change register, incident history and direct agency customers to a reporting period. Identify the previous report boundary, delivery channel and necessary-party roster including FedRAMP, all using agency customers and parties required by agreements.", "A dated reporting-input map identifies source owners, period boundaries, recipient coverage and missing inputs."},
		{"ccm-review-meetings", "Quarterly review coordination", "Agency engagement owner", "Link the most recent Ongoing Certification Report to a meeting calendar, agency-relevant agenda, necessary-party roster and meeting access mechanism. Identify the certification class and retain the decision to host where hosting is recommended or permitted.", "The meeting series identifies report versions, class-specific hosting decision, agency audience and accessible invitation route."},
		{"ccm-release-review", "Responsible disclosure review", "Security communications owner", "Identify the report, presentation or recording revision proposed for release and its intended audience. Map sensitive technical detail and agency information to redaction decisions; distinguish restricted necessary-party distribution from optional public release.", "The release workflow binds audience and disclosure judgment to exact content revisions, including comments, questions and names in recordings."},
	}, []string{"All Necessary Parties", "Quarterly Review", "Ongoing Certification Report (OCR)", "Accepted Vulnerability", "FedRAMP Reportable Incident", "Responsibly", "Likely", "Regularly", "Security Category"})
}

