func ccmDisclosure(object string, optional, agencyRemoval bool) communicationRecipe {
	r := communicationRecipe{cap: "ccm-release-review", owner: "Security communications owner", purpose: "Evaluate disclosure risk for the exact " + object + " and audience before distribution.", setup: "Identify the proposed " + object + " revision and recipients; locate sensitive technical details, vulnerability disclosures and customer information requiring review.", operate: "Review the " + object + " for disclosures likely to adversely affect the offering; revise or withhold unsafe content and retain the release judgment.", records: "Original and released " + object + " revisions, audience, sensitive-content review, redaction decisions, likely-adverse-effect assessment and actual distribution record.", review: "Compare the reviewed revision to what was distributed and evaluate the judgment about likely adverse effect; absence of an observed incident does not prove responsible disclosure.", scope: "The precise " + object + " release, including attachments and intended recipients.", timing: "Retain review, release and distribution dates for each disclosure; this rule does not create a numeric review interval.", insufficient: "A generic communications policy, approval unrelated to the released revision or absence of complaints.", trigger: "event"}
	if optional {
		r.operate = "If the provider elects public or other-party sharing, first determine that releasing the " + object + " will NOT likely adversely affect the offering. Record non-election without treating optional sharing as a duty."
	}
	if agencyRemoval {
		r.operate += " Remove ALL agency information, including comments, questions and names, as well as making the no-likely-adverse-effect determination."
		r.records += " Retain a comparison demonstrating removal of all agency information across audio/video, text and metadata."
		r.review += " Verify both conditions independently: removal of all agency information and the adverse-effect determination."
	}
	return r
}
